+++ b/scripts/contentful/setup/bootstrapSpace.mjs
@@ -40,6 +40,7 @@ const TARGET_ENVIRONMENTS = ['dev', 'test', 'sit', 'staging', 'uat'];
 const LOCALES = [
   { code: 'en',    name: 'English (AU)',             default: true,  fallbackCode: null  },
   { code: 'en-US', name: 'English (US)',              default: false, fallbackCode: 'en' },
+  { code: 'en-CA', name: 'English (US International)', default: false, fallbackCode: 'en' },
   { code: 'en-GB', name: 'English (UK / EU)',         default: false, fallbackCode: 'en' },
   { code: 'fr',    name: 'French (EU)',               default: false, fallbackCode: 'en' },
   { code: 'it',    name: 'Italian (EU)',              default: false, fallbackCode: 'en' },
@@ -61,10 +62,65 @@ const results = {
   aliases: { created: [], updated: [], skipped: [] },
 };

+/**
+ * Create any missing LOCALES in one environment. Idempotent — existing codes are skipped.
+ *
+ * Split out of main() and parameterised because locales do NOT propagate to an environment
+ * created before them: a clone inherits master's locales as they stood at clone time, and
+ * nothing back-fills afterwards. Provisioning master first fixes new clones; re-running this
+ * per target environment fixes the ones that already existed.
+ */
+async function provisionLocales(client, environmentId) {
+  const existing = await getExistingLocaleCodes(client, environmentId);
+  log.info(`Existing locales in '${environmentId}': ${existing.join(', ')}`);
+
+  for (const locale of LOCALES) {
+    if (existing.includes(locale.code)) {
+      log.skip(`Locale '${locale.code}' already exists in '${environmentId}'`);
+      results.locales.skipped.push(`${environmentId}/${locale.code}`);
+      continue;
+    }
+    if (DRY_RUN) {
+      log.info(`[dry-run] Would create locale '${locale.code}' (${locale.name}) in '${environmentId}'`);
+      results.locales.created.push(`${environmentId}/${locale.code}`);
+      continue;
+    }
+    const payload = {
+      name: locale.name,
+      code: locale.code,
+      default: locale.default,
+      // Non-default locales are optional: required-localized fields can publish with
+      // only 'en' set — translation is a separate, later pass through the translation
+      // app, not a precondition for publishing English content. fallbackCode above
+      // covers reads in the meantime.
+      optional: !locale.default,
+    };
+    if (locale.fallbackCode) payload.fallbackCode = locale.fallbackCode;
+
+    try {
+      await client.locale.create({ environmentId }, payload);
+      log.success(`Created locale '${locale.code}' (${locale.name}) in '${environmentId}'`);
+      results.locales.created.push(`${environmentId}/${locale.code}`);
+    } catch (err) {
+      log.warn(
+        `Failed to create locale '${locale.code}' in '${environmentId}': ${err.message ?? err}. Skipping — re-run later to retry.`,
+      );
+      results.locales.failed.push(`${environmentId}/${locale.code}`);
+    }
+  }
+}
+
 async function main() {
   const client = createClient();

-  // ── 1. Environments ─────────────────────────────────────────────────────────
+  // ── 1. Locales in master ────────────────────────────────────────────────────
+  // Before environments, deliberately: §2 clones from master, and a clone only inherits the
+  // locales master had at clone time. Creating them after would leave every new environment
+  // without them, which is what previously happened.
+  log.section('Locales (master)');
+  await provisionLocales(client, 'master');
+
+  // ── 2. Environments ─────────────────────────────────────────────────────────
   log.section('Environments');

   const { items: envItems } = await client.environment.getMany({ query: { limit: 100 } });
@@ -72,10 +128,15 @@ async function main() {
   const existingByName = new Map(envItems.map((e) => [e.name,   e]));
   log.info(`Existing: ${[...existingById.keys()].join(', ')}`);

+  // Environments that exist (or will) and are therefore safe to provision locales into below.
