-  log.section('Locales');
-
-  const existingLocales = await getExistingLocaleCodes(client, 'master');
-  log.info(`Existing locales in master: ${existingLocales.join(', ')}`);
-
-  for (const locale of LOCALES) {
-    if (existingLocales.includes(locale.code)) {
