-      // covers reads in the meantime.
-      optional: !locale.default,
-    };
-    if (locale.fallbackCode) payload.fallbackCode = locale.fallbackCode;
+  // ── 3. Locales in the target environments ───────────────────────────────────
+  // Environments cloned in §2 already inherited master's locales, so this is a no-op for them.
+  // It exists for environments that pre-dated a locale being added to LOCALES — those never
+  // receive it otherwise, because a clone only inherits once and nothing back-fills.
+  log.section('Locales (target environments)');

-    try {
-      await client.locale.create({ environmentId: 'master' }, payload);
-      log.success(`Created locale '${locale.code}' (${locale.name})`);
-      results.locales.created.push(locale.code);
