     5	
     6	import { createClient as createCMAClient } from 'contentful-management';
     7	
     8	export const log = {
     9	  info: (msg) => console.log(`  ℹ️  ${msg}`),
    10	  success: (msg) => console.log(`  ✅  ${msg}`),
    11	  skip: (msg) => console.log(`  ⏭️   ${msg}`),
    12	  warn: (msg) => console.warn(`  ⚠️  ${msg}`),
    13	  error: (msg) => console.error(`  ❌  ${msg}`),
    14	  section: (msg) => console.log(`\n── ${msg} ──`),
    15	};
