    59	// ── .env parsing ─────────────────────────────────────────────────────────────
    60	
    61	function parseEnv(content) {
    62	  return content.split('\n').map((line) => {
    63	    if (line.startsWith('#') || line.trim() === '') {
    64	      return { type: 'raw', value: line };
    65	    }
    66	    const eqIdx = line.indexOf('=');
    67	    if (eqIdx === -1) return { type: 'raw', value: line };
    68	    return { type: 'var', key: line.slice(0, eqIdx), value: line.slice(eqIdx + 1) };
    69	  });
    70	}
    71	
    72	function serializeEnv(entries) {
    73	  return entries.map((e) => (e.type === 'var' ? `${e.key}=${e.value}` : e.value)).join('\n');
    74	}
